import React, { useState, useEffect, useRef } from 'react';
import Plotly from 'plotly.js';

const DataPlot = ({ logData, columns }) => {
	const plotContainer = useRef(null); // Ref to the div where the plot will render
	const [selectedPids, setSelectedPids] = useState([]);
	const [pidOptions, setPidOptions] = useState([]);

	// This effect identifies which columns are numeric and can be plotted.
	useEffect(() => {
		if (logData && logData.length > 0 && columns && columns.length > 0) {
			const numericCols = columns.filter(col =>
				col !== 'data_id' && col !== 'timestamp' && col !== 'operating_state' &&
				typeof logData[0][col] === 'number'
			);
			setPidOptions(numericCols);
			if (numericCols.length > 0) {
				setSelectedPids([numericCols[0]]);
			}
		}
	}, [logData, columns]);

	// This effect creates and updates the plot whenever the data or selection changes.
	useEffect(() => {
		if (!logData || selectedPids.length === 0 || !plotContainer.current) {
			// If there's no data or container, clear any existing plot.
			if(plotContainer.current) Plotly.purge(plotContainer.current);
			return;
		}

		const timestamps = logData.map(d => new Date(d.timestamp));
		const plotData = selectedPids.map(pid => ({
			x: timestamps,
			y: logData.map(d => d[pid]),
			type: 'scatter',
			mode: 'lines',
			name: pid
		}));

		const layout = {
			title: 'Log Data',
			xaxis: { title: 'Timestamp' },
			yaxis: { title: 'Value' },
			showlegend: true,
			autosize: true
		};

		// Plotly.react will efficiently re-render the plot with new data.
		Plotly.react(plotContainer.current, plotData, layout, {responsive: true});

	}, [logData, selectedPids, columns]);


	const handlePidChange = (event) => {
		const { options } = event.target;
		const selectedValues = [];
		for (let i = 0, l = options.length; i < l; i++) {
			if (options[i].selected) {
				selectedValues.push(options[i].value);
			}
		}
		setSelectedPids(selectedValues);
	};

	if (!logData || logData.length === 0) {
		return <p>No data available to plot.</p>;
	}

	return (
		<div className="data-plot-container" style={{ width: '100%', height: '500px' }}>
			<div className="plot-controls">
				<label htmlFor="pid-selector">Select PIDs to plot:</label>
				<select
					id="pid-selector"
					multiple
					value={selectedPids}
					onChange={handlePidChange}
					style={{ width: '100%', height: '100px', marginBottom: '10px' }}
				>
					{pidOptions.map(pid => (
						<option key={pid} value={pid}>{pid}</option>
					))}
				</select>
			</div>
			{/* This div is the target for the Plotly chart */}
			<div ref={plotContainer} style={{ width: '100%', height: '400px' }}></div>
		</div>
	);
};

export default DataPlot;
